271	    private static Simple_fcn inferWithCoercionOrFail(List<FValue> args,
272	                                                      GenericFunctionOrMethod appliedThing,
273	                                                      Environment envForInference) {
274	        final List<FValue> originalArgs = args;
275	        GenericTypeInstance selfType = null;
276	        if (appliedThing instanceof GenericFunctionalMethod) {
277	            GenericFunctionalMethod gfm = (GenericFunctionalMethod) appliedThing;
278	            FTypeGeneric declaredSelfType = gfm.getSelfParameterTypeAsGeneric();
279	            FValue selfArg = args.get(gfm.getSelfParameterIndex());
280	            if (!(selfArg.type() instanceof GenericTypeInstance)) return null;
281	            selfType = (GenericTypeInstance) selfArg.type();
282	            for (FType ft : selfType.getTransitiveExtends()) {
283	                if (ft instanceof GenericTypeInstance && ((GenericTypeInstance) ft).getGeneric().equals(
284	                        declaredSelfType)) {
285	                    selfType = (GenericTypeInstance) ft;
286	                    break;
287	                }
288	            }
289	            envForInference = selfType.getWithin();
290	        }
291	        List<StaticParam> tparams = appliedThing.getStaticParams();
292	        List<Param> params = appliedThing.getParams();
293	        EvalType et = new EvalType(appliedThing.getWithin());
294	        BoundingIntervals abm = new BoundingIntervals(true);
295	        Set<String> tp_set = new HashSet<String>();
296	        Set<String> typeParams = new HashSet<String>();
297	        Map<String, List<FType>> bounds = new HashMap<String, List<FType>>();
298	        List<StaticParam> rechecks = new ArrayList<StaticParam>();
299	        for (StaticParam sp : tparams) {
300	            String name = NodeUtil.getName(sp);
301	            tp_set.add(name);
302	            if (!NodeUtil.isTypeParam(sp)) continue;
303	            typeParams.add(name);
304	            List<FType> bs = new ArrayList<FType>();
305	            bounds.put(name, bs);
306	            for (Type tr : sp.getExtendsClause()) {
307	                try {
308	                    FType tt = et.evalType(tr);
309	                    abm.meetPut(name, tt);
310	                    bs.add(tt);
311	                }
312	                catch (FortressException pe) {
313	                    if (!rechecks.contains(sp)) rechecks.add(sp);
314	                }
315	            }
316	        }
317	        if (params.size() == 1 && args.size() != 1 && !NodeUtil.isVarargsParam(params.get(0))) {
318	            args = Useful.<FValue>list(FTuple.make(args));
319	        }
320	        /* The first pass: the arguments whose declared type is not a type parameter alone. */
321	        Map<String, List<FValue>> lone = new LinkedHashMap<String, List<FValue>>();
322	        Map<String, Type> loneType = new HashMap<String, Type>();
323	        Set<String> fixedElsewhere = new HashSet<String>();
324	        Iterator<Param> pit = params.iterator();
325	        Param p = null;
326	        for (FValue a : args) {
327	            FType at = a.type();
328	            if (at == null) return null;
329	            if (pit.hasNext()) p = pit.next();
330	            else if (p == null) return null;
331	            if (NodeUtil.isVarargsParam(p)) {
332	                Type ty = p.getVarargsType().unwrap();
333	                fixedElsewhere.addAll(mentions(ty, tp_set));
334	                at.unify(envForInference, tp_set, abm, ty);
335	                continue;
336	            }
337	            Option<TypeOrPattern> t = p.getIdType();
338	            if (t.isNone()) {
339	                boolean isSelf = p.getName().toString().equals("self");
340	                if (isSelf && appliedThing instanceof GenericFunctionalMethod.Own) continue;
341	                if (!(isSelf && appliedThing instanceof GenericFunctionalMethod)) {
342	                    return null;
343	                }
344	                Type selfInst = selfType.getGeneric().getInstantiationForFunctionalMethodInference();
345	                at.unify(envForInference, tp_set, abm, selfInst);
346	                fixedElsewhere.addAll(mentions(selfInst, tp_set));
347	                continue;
348	            }
349	            Type ty = NodeUtil.optTypeOrPatternToType(t).unwrap();
350	            if (ty instanceof VarType && typeParams.contains(NodeUtil.nameString(((VarType) ty).getName()))) {
351	                String n = NodeUtil.nameString(((VarType) ty).getName());
352	                if (!lone.containsKey(n)) {
353	                    lone.put(n, new ArrayList<FValue>());
354	                    loneType.put(n, ty);
355	                }
356	                lone.get(n).add(a);
357	                continue;
358	            }
359	            Set<String> m = mentions(ty, tp_set);
360	            if (m.isEmpty()) continue;
361	            fixedElsewhere.addAll(m);
362	            at.unify(envForInference, tp_set, abm, ty);
363	        }
364	        /* The second pass: each type parameter that stands alone and that the first pass did not fix. */
365	        for (Map.Entry<String, List<FValue>> e : lone.entrySet()) {
366	            String n = e.getKey();
367	            FType fixed = abm.get(n);
368	            if (fixedElsewhere.contains(n) && fixed != null && !(fixed instanceof BottomType)) continue;
369	            boolean selfBounded = selfBounded(n, rechecks);
370	            FType chosen = narrowest(n, e.getValue(), abm, rechecks, tp_set, envForInference, bounds.get(n),
371	                                     appliedThing.getWithin(), selfBounded);
372	            FType bound = boundOf(abm, n);
373	            if (chosen == null && !selfBounded && allSubtypes(e.getValue(), bound)) chosen = bound;
374	            if (TRACE != null && !selfBounded) {
375	                FType before = narrowest(n, e.getValue(), abm, rechecks, tp_set, envForInference, bounds.get(n),
376	                                         appliedThing.getWithin(), true);
377	                if (before == null || !before.equals(chosen)) {
378	                    traceInstance("lone", appliedThing, n, before == null ? "join" : before, chosen,
379	                                  typesOf(e.getValue()));
380	                }
381	            }
382	            if (chosen != null) {
383	                abm.joinPut(n, chosen);
384	            } else {
385	                for (FValue a : e.getValue()) a.type().unify(envForInference, tp_set, abm, loneType.get(n));
386	            }
387	        }
388	        MakeInferenceSpecific mis = new MakeInferenceSpecific(abm);
389	        Option<Type> opt_rt = appliedThing.getReturnType();
390	        if (opt_rt.isSome()) opt_rt.unwrap().accept(mis);
391	        for (StaticParam tp : rechecks) {
392	            FType t = abm.get(NodeUtil.getName(tp));
393	            if (t == null) t = BottomType.ONLY;
394	            for (Type tr : tp.getExtendsClause()) t.unify(envForInference, tp_set, abm, tr);
395	        }
396	        Set<String> fixable = new HashSet<String>(fixedElsewhere);
397	        fixable.addAll(lone.keySet());
398	        ArrayList<FType> tl = instanceOf(tparams, abm, fixable, rechecks, true, appliedThing, originalArgs);
399	        Simple_fcn sfcn = appliedThing.typeApply(tl);
400	        /* Every argument admitted by the instance's domain, by subtyping or by one coercion. */
401	        List<FValue> fargs = sfcn.fixupArgCount(originalArgs);
402	        if (fargs == null) return null;
403	        List<FType> dom = sfcn.getDomain();
404	        for (int j = 0; j < fargs.size(); j++) {
405	            if (!Coercions.admits(Useful.clampedGet(dom, j).deRest(), fargs.get(j))) return null;
406	        }
407	        return sfcn;
408	    }
